INSERT INTO lesson (title, content, file_paths) VALUES ('Xử lý mảng trong Java', 'Ngôn ngữ Java được sử dụng rộng rãi trong phát triển phần mềm và ứng dụng hệ thống. Nó có thể thực hiện nhiều chức năng khác nhau từ phát triển ứng dụng đến xử lý dữ liệu.', '[]');
INSERT INTO lesson (title, content, file_paths) VALUES ('Vòng lặp trong PHP', 'Vòng lặp trong PHP cho phép bạn thực hiện các hành động nhiều lần, rất hữu ích khi bạn cần lặp qua dãy dữ liệu hoặc thực hiện các phép toán lặp đi lặp lại.', '[]');
INSERT INTO lesson (title, content, file_paths) VALUES ('Xử lý mảng trong SQL', 'Xử lý mảng trong SQL cho phép bạn làm việc với các dãy giá trị, giúp đơn giản hóa việc lưu trữ và xử lý dữ liệu.', '[]');
